","bytes":435},{"id":"ev-5ddd4fd9ff8ad0e66559","repository":"go-gitea/gitea","sourceRef":"fc28937a8d772fe9e4025c9b5f24d5db4d86610b","path":"models/issues/issue_user.go","sha256":"64c2a0628d46bf2927688c29dc16fd74b1d31005873653b0f55bb4ec6ca6d9b9","startLine":28,"endLine":55,"text":"28 | func NewIssueUsers(ctx context.Context, repo *repo_model.Repository, issue *Issue) error {
29 | 	assignees, err := repo_model.GetRepoAssignees(ctx, repo)
30 | 	if err != nil {
31 | 		return fmt.Errorf("getAssignees: %w", err)
32 | 	}
33 | 
34 | 	// Poster can be anyone, append later if not one of assignees.
35 | 	isPosterAssignee := false
36 | 
37 | 	// Leave a seat for poster itself to append later, but if poster is one of assignee
