304 | 				return err
305 | 			}
306 | 			attachments[i].IssueID = issueID
307 | 			if err := repo_model.UpdateAttachment(ctx, attachments[i]); err != nil {
308 | 				return fmt.Errorf("update attachment [id: %d]: %w", attachments[i].ID, err)
309 | 			}
310 | 		}
311 | 		return nil
