","bytes":602},{"id":"ev-0809f8354fc28d4824d5","repository":"go-gitea/gitea","sourceRef":"fc28937a8d772fe9e4025c9b5f24d5db4d86610b","path":"models/issues/milestone.go","sha256":"74e8568d9e244eca6e373cf840531adcce4a8907f5572dec517d2aa0056c446c","startLine":183,"endLine":204,"text":"183 | func UpdateMilestoneCounters(ctx context.Context, id int64) error {
184 | 	e := db.GetEngine(ctx)
185 | 	_, err := e.ID(id).
186 | 		Cols("num_issues", "num_closed_issues").
187 | 		SetExpr("num_issues", builder.Select("count(*)").From("issue").Where(
188 | 			builder.Eq{"milestone_id": id},
189 | 		)).
190 | 		SetExpr("num_closed_issues", builder.Select("count(*)").From("issue").Where(
191 | 			builder.Eq{
192 | 				"milestone_id": id,
193 | 				"is_closed":    true,
194 | 			},
195 | 		)).
196 | 		Update(&Milestone{})
197 | 	if err != nil {
198 | 		return err
199 | 	}
200 | 	_, err = e.Exec("UPDATE `milestone` SET completeness=(CASE WHEN is_closed = ? AND num_issues = 0 THEN 100 ELSE 100*num_closed_issues/(CASE WHEN num_issues > 0 THEN num_issues ELSE 1 END) END) WHERE id=?",
201 | 		true, id,
202 | 	)
