	}
	issuePin, err := GetIssuePin(ctx, issue)
	if err != nil && !db.IsErrNotExist(err) {
		return err
	}

	if issuePin != nil {
		issue.PinOrder = issuePin.PinOrder
	} else {
		issue.PinOrder = -1
	}
	return nil
}

